["name"] = "Smart Detection",
["width"] = 1,
},
{
["type"] = "toggle",
["default"] = false,
["desc"] = "Enabling this option will give a faint glow around the icon when you are in ~40y range to a player needing the buff and you are able to apply the buff. This will increase CPU load by a bit.",
["key"] = "option2",
["useDesc"] = true,
["name"] = "Range Checking",
["width"] = 1,
},
},
["adjustedMax"] = "",
["adjustedMin"] = "",
["yOffset"] = 0,
