["custom"] = "function(a, event, unit, type)\n    local whirlwindID = 85739\n    local power = aura_env.get_aura_stacks(whirlwindID) or 0\n    \n    if power > 0 then\n        for i = 1, 4 do\n            a[i] = {\n                show = true, \n                changed = true,\n                progressType = \"static\", \n                total = 1, \n                value = power >= i and 1 or 0,\n                index = i,\n                totalPower = power,\n                full = power >= 4\n            }\n        end\n        return true\n    else\n        for i = 1, 4 do\n            a[i] = {\n                show = false,\n                changed = true\n            }\n        end\n        return true\n    end\nend",
